import{_ as t}from"./chunks/image-006.BzaDFqgA.js";import{_ as a,o as p,c as o,a3 as _}from"./chunks/framework.DdpBa4_E.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/xuehui-tiwen/18-寻找论题.md","filePath":"books/xuehui-tiwen/18-寻找论题.md","lastUpdated":1781367562000}'),r={name:"books/xuehui-tiwen/18-寻找论题.md"};function s(i,e,n,d,l,c){return p(),o("div",null,[...e[0]||(e[0]=[_('<h2 id="寻找论题" tabindex="-1">寻找论题 <a class="header-anchor" href="#寻找论题" aria-label="Permalink to &quot;寻找论题&quot;">​</a></h2><p>我们该怎样着手确定基本的问题或者说论题呢？有时这很简单：写作者或发言者会直接告诉你论题是什么。或者，你可以在文章的正文中找到论题，通常在文章的开头甚至标题中就可以找到它。如果论题直截了当地说出来，会有一些提示性的话语。</p><p>我想问的问题是：我们为什么一定要有规范烟草制品的各种法律呢？</p><p>降低法定饮酒年龄：这样做到底对不对？</p><p>学校到底该不该提供性教育？</p><p>可惜的是，论题中涉及的问题并不总是直截了当地提出来，很多时候需要我们从其他线索中去推断。例如，很多写作者或发言者会对他们关心的一些热点事件进行回应，例如发生在校园里的一系列暴力事件。问一问“这个人是在对什么事进行回应”常常能帮你找出文章或发言的中心论题。还有一个比较好的线索是作者的背景，例如他所属的组织机构。所以在你想要确定论题的时候，有必要去查一查写作者的背景信息。</p><p>在识别论题的时候，千万不要以为存在且只存在一种正确的陈述论题的方法。一旦你找到整篇文章或整个发言都在论述的问题，以及该问题和该文章（或该发言）间的联系，你就已经找到了一个引发了争论的论题。只要确定你所谓的论题符合“论题”的界定标准即可。</p><p>在论题没有直截了当地陈述出来时，最有效的方法是先找准结论。很多情况下，必须先找到结论，才能确认论题。因此，在这种情况下，批判性评价的第一步就是找出结论之所在——这通常是一个比较难的步骤。</p><p>只有找到结论，我们才能做出批判性的评价！</p><p>我们一起看看如何着手寻找结论这一至关重要的结构要素。</p><p><img src="'+t+'" alt="" loading="lazy"></p><p>注意：所谓结论，即写作者或发言者希望你接收的信息。</p>',12)])])}const h=a(r,[["render",s]]);export{f as __pageData,h as default};
